class Solution {
    public int numSubarrayProductLessThanK(int[] nums, int k) {
        if (k <= 1) return 0;

        int answer = 0;
        int left = 0;
        long product = 1L;
        for (int right = 0; right < nums.length; right++) {
            product *= nums[right];
            while (product >= k) {
                product /= nums[left];
                left++;
            }
            answer += right - left + 1;
        }
        return answer;
    }
}

class Solution {
    public int numSubarrayProductLessThanK(int[] nums, int k) {
        if (k <= 1) return 0;

        int answer = 0;
        int left = 0;
        long product = 1L;
        for (int right = 0; right < nums.length; right++) {
            if (nums[right] >= k) {
                product = 1L;
                left = right + 1;
                continue;
            }

            product *= nums[right];
            while (product >= k) {
                product /= nums[left];
                left++;
            }
            answer += right - left + 1;
        }
        return answer;
    }
}

class Solution {
    public int numSubarrayProductLessThanK(int[] nums, int k) {
        if (k <= 1) return 0;

        int n = nums.length;
        double[] prefix = new double[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + Math.log(nums[i]);
        }

        int answer = 0;
        double logK = Math.log(k);
        for (int start = 0; start < n; start++) {
            double limit = prefix[start] + logK - 1e-12;
            int firstGreater = upperBound(prefix, limit);
            answer += Math.max(0, firstGreater - start - 1);
        }
        return answer;
    }

    private int upperBound(double[] values, double target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public int numSubarrayProductLessThanK(int[] nums, int k) {
        if (k <= 1) return 0;

        int answer = 0;
        for (int start = 0; start < nums.length; start++) {
            long product = 1L;
            for (int end = start; end < nums.length; end++) {
                product *= nums[end];
                if (product >= k) {
                    break;
                }
                answer++;
            }
        }
        return answer;
    }
}
